import { sql, type SQL } from "drizzle-orm";
import { text, timestamp, uuid, type AnyPgColumn } from "drizzle-orm/pg-core";

// Shared column builders and CHECK expressions. Conventions (docs/database.md):
// - internal IDs are UUIDs, external UniFi IDs live in their own columns,
// - all points in time are `timestamptz` (absolute instants, no implicit server time zone),
// - DB columns are snake_case, TypeScript fields camelCase.

/** Primary key, generated by PostgreSQL 18's native, time-ordered `uuidv7()`. */
export const id = () =>
  uuid("id")
    .primaryKey()
    .default(sql`uuidv7()`);

export const timestamptz = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

/** `created_at` / `updated_at`; `updated_at` is set on every Drizzle update, using the DB clock. */
export const timestamps = () => ({
  createdAt: timestamptz("created_at").notNull().defaultNow(),
  updatedAt: timestamptz("updated_at")
    .notNull()
    .defaultNow()
    .$onUpdate(() => sql`now()`),
});

/**
 * Smart detection types as reported by Protect. Deliberately `text[]` instead of a PostgreSQL
 * enum: Protect adds new types over time, and an unknown type must not make inserts fail.
 */
export const smartDetectTypes = (name: string) => text(name).array().notNull().default(sql`'{}'::text[]`);

/** CHECK expression: text must not be empty or whitespace only. */
export const notBlank = (column: AnyPgColumn): SQL => sql`btrim(${column}) <> ''`;

/**
 * CHECK expression: column value is one of `values`. Used instead of PostgreSQL enums for
 * statuses we own: extending the list is a plain constraint replacement in a migration.
 * Values are compile-time constants, so inlining them as literals is safe.
 */
export const oneOf = (column: AnyPgColumn, values: readonly string[]): SQL => {
  if (values.length === 0 || !values.every((value) => /^[A-Za-z]+$/.test(value))) {
    throw new Error(`oneOf() expects plain identifiers, got: ${values.join(", ")}`);
  }
  return sql`${column} in (${sql.raw(values.map((value) => `'${value}'`).join(", "))})`;
};

/** CHECK expression: optional end is not before start. */
export const endNotBeforeStart = (start: AnyPgColumn, end: AnyPgColumn): SQL =>
  sql`${end} is null or ${end} >= ${start}`;
